# ============================================================
# AUTHENTIFICATION
# ------------------------------------------------------------
# Stockage local (fichier JSON à côté du script) : sel + hash
# SHA-256 du mot de passe. Aucun mot de passe en clair n'est
# jamais conservé sur disque.
#
# Mot de passe par défaut : P@sse123
# -> "doit_changer" force l'utilisateur à définir un nouveau
#    mot de passe dès la première connexion réussie.
# ============================================================

AUTH_FILE = Path(__file__).resolve().parent / "credentials.json"
MOT_DE_PASSE_DEFAUT = "P@sse123"


def hacher_mot_de_passe(mot_de_passe: str, sel: str) -> str:
    return hashlib.sha256((sel + mot_de_passe).encode("utf-8")).hexdigest()


def initialiser_credentials() -> dict:
    """Crée le fichier de credentials avec le mot de passe par défaut
    s'il n'existe pas encore (premier démarrage de l'application)."""
    if not AUTH_FILE.exists():
        sel = secrets.token_hex(16)
        credentials = {
            "utilisateur": "admin",
            "sel": sel,
            "hash": hacher_mot_de_passe(MOT_DE_PASSE_DEFAUT, sel),
            "doit_changer": True,
            "derniere_modification": None,
        }
        AUTH_FILE.write_text(json.dumps(credentials, indent=2), encoding="utf-8")
    return json.loads(AUTH_FILE.read_text(encoding="utf-8"))


def sauvegarder_credentials(credentials: dict) -> None:
    AUTH_FILE.write_text(json.dumps(credentials, indent=2), encoding="utf-8")


def verifier_mot_de_passe(mot_de_passe: str, credentials: dict) -> bool:
    return hacher_mot_de_passe(mot_de_passe, credentials["sel"]) == credentials["hash"]


def changer_mot_de_passe(nouveau_mot_de_passe: str, credentials: dict) -> dict:
    sel = secrets.token_hex(16)
    credentials["sel"] = sel
    credentials["hash"] = hacher_mot_de_passe(nouveau_mot_de_passe, sel)
    credentials["doit_changer"] = False
    credentials["derniere_modification"] = datetime.now().strftime("%d/%m/%Y %H:%M")
    sauvegarder_credentials(credentials)
    return credentials


def mot_de_passe_valide(mot_de_passe: str) -> tuple[bool, str]:
    """Règles minimales de robustesse pour un mot de passe pro."""
    if len(mot_de_passe) < 8:
        return False, "Le mot de passe doit contenir au moins 8 caractères."
    if not any(c.isupper() for c in mot_de_passe):
        return False, "Le mot de passe doit contenir au moins une majuscule."
    if not any(c.isdigit() for c in mot_de_passe):
        return False, "Le mot de passe doit contenir au moins un chiffre."
    if not any(not c.isalnum() for c in mot_de_passe):
        return False, "Le mot de passe doit contenir au moins un caractère spécial."
    return True, ""


CREDENTIALS = initialiser_credentials()

