def afficher_ecran_connexion():
    _, col_centre, _ = st.columns([1, 1.2, 1])

    with col_centre:
        with st.container(border=True):
            st.markdown(
                f"""
                <div style="text-align:center;">
                    <div class="login-logo">📊</div>
                    <div class="login-titre">{NOM_APPLICATION}</div>
                    <div class="login-sous-titre">Portail de réconciliation multi-partenaires</div>
                </div>
                """,
                unsafe_allow_html=True,
            )

            with st.form("formulaire_connexion", clear_on_submit=False):
                utilisateur = st.text_input("Identifiant", value=CREDENTIALS.get("utilisateur", "admin"), disabled=True)
                mot_de_passe = st.text_input("Mot de passe", type="password", placeholder="••••••••")
                connexion = st.form_submit_button("Se connecter", use_container_width=True, type="primary")

            if connexion:
                if verifier_mot_de_passe(mot_de_passe, CREDENTIALS):
                    st.session_state.authentifie = True
                    st.session_state.mdp_change_ok = not CREDENTIALS.get("doit_changer", False)
                    st.rerun()
                else:
                    st.error("Identifiant ou mot de passe incorrect.")

            st.markdown(
                f'<div class="login-footer">Accès réservé au personnel autorisé — '
                f'{NOM_APPLICATION} v{VERSION_APPLICATION}</div>',
                unsafe_allow_html=True,
            )


def afficher_ecran_changement_mdp_obligatoire():
    _, col_centre, _ = st.columns([1, 1.2, 1])

    with col_centre:
        with st.container(border=True):
            st.markdown(
                """
                <div style="text-align:center;">
                    <div class="login-logo">🔐</div>
                    <div class="login-titre">Nouveau mot de passe requis</div>
                    <span class="badge-securite">⚠️ Mot de passe par défaut détecté</span>
                    <div class="login-sous-titre">Pour des raisons de sécurité, vous devez définir
                    un nouveau mot de passe avant de continuer.</div>
                </div>
                """,
                unsafe_allow_html=True,
            )

            with st.form("formulaire_changement_obligatoire"):
                nouveau = st.text_input("Nouveau mot de passe", type="password")
                confirmation = st.text_input("Confirmer le nouveau mot de passe", type="password")
                valider = st.form_submit_button("Définir mon mot de passe", use_container_width=True, type="primary")

            if valider:
                if nouveau != confirmation:
                    st.error("Les deux mots de passe ne correspondent pas.")
                elif nouveau == MOT_DE_PASSE_DEFAUT:
                    st.error("Le nouveau mot de passe doit être différent du mot de passe par défaut.")
                else:
                    ok, message = mot_de_passe_valide(nouveau)
                    if not ok:
                        st.error(message)
                    else:
                        global CREDENTIALS
                        CREDENTIALS = changer_mot_de_passe(nouveau, CREDENTIALS)
                        st.session_state.mdp_change_ok = True
                        st.success("Mot de passe mis à jour avec succès.")
                        st.rerun()

            st.caption("Le mot de passe doit contenir au moins 8 caractères, une majuscule, un chiffre et un caractère spécial.")


# ------------------------------------------------------------
# PORTE D'ENTRÉE — bloque tout le reste de l'application tant
# que l'utilisateur n'est pas authentifié, puis tant qu'il n'a
# pas changé le mot de passe par défaut.
# ------------------------------------------------------------

if not st.session_state.authentifie:
    afficher_ecran_connexion()
    st.stop()

if CREDENTIALS.get("doit_changer", False) and not st.session_state.get("mdp_change_ok", False):
    afficher_ecran_changement_mdp_obligatoire()
    st.stop()


