def safe_df(response):
    try:
        if response.status_code != 200:
            return pd.DataFrame()
        data = response.json()
        if isinstance(data, list):
            return pd.DataFrame(data)
        if isinstance(data, dict):
            return pd.DataFrame([data])
        return pd.DataFrame()
    except Exception:
        return pd.DataFrame()


def charger_figure(endpoint: str, params: dict, hauteur: int = None):
    """Récupère une figure Plotly déjà entièrement construite côté API
    (couleurs, légende, titre...) et la désérialise. Ne fait AUCUNE
    construction ni mise en forme : juste un GET + pio.from_json.
    Seul ajout : si `hauteur` est fourni, on ajuste UNIQUEMENT la
    hauteur d'affichage (update_layout)."""
    try:
        r = requests.get(f"{API_BASE_URL}{endpoint}", params=params, timeout=30)
    except Exception as e:
        st.error(f"Erreur chargement graphique : {e}")
        return None

    if r.status_code != 200:
        st.warning(r.text)
        return None

    data = r.json()
    if not data:
        return None

    fig = pio.from_json(json.dumps(data))
    if hauteur:
        fig.update_layout(height=hauteur)
    return fig


# ============================================================
# GRAPHIQUES — entièrement construits côté API (reconc.py) :
# couleurs, légende, taux au centre, courbes. Streamlit se
# contente de récupérer les DEUX figures Plotly déjà prêtes et
# de les afficher côte à côte. Aucune construction ici.
# Concerne uniquement le mode "two_pointers" (colonne SENS produite
# par run_reconciliation).
# ============================================================

def afficher_graphes_reconciliation(partenaire, hauteur_graphe: int):

    st.markdown('<div class="carte-section">', unsafe_allow_html=True)
    col_gauche, col_droite = st.columns(2)

    with col_gauche:
        fig_statut = charger_figure(
            "/db/reconciliation-graphe-statut",
            {"partenaire": partenaire},
            hauteur=hauteur_graphe,
        )
        if fig_statut:
            st.plotly_chart(fig_statut, use_container_width=True)
        else:
            st.info("Aucune donnée de répartition disponible. Lance d'abord une réconciliation.")

    with col_droite:
        type_transaction = st.selectbox(
            "Sens",
            options=["W2B", "B2W"],
            key=f"type_transaction_{partenaire}"
        )
        fig_evolution = charger_figure(
            "/db/reconciliation-graphe-evolution",
            {"partenaire": partenaire, "type_transaction": type_transaction},
            hauteur=hauteur_graphe,
        )
        if fig_evolution:
            st.plotly_chart(fig_evolution, use_container_width=True)
        else:
            st.info("Aucune donnée d'évolution disponible pour ce sens.")
    st.markdown('</div>', unsafe_allow_html=True)


def charger_carte_resume(partenaire):
    """Récupère la carte résumé (HTML déjà entièrement construit et
    formaté côté API). Streamlit ne fait qu'un GET + affichage."""
    try:
        r = requests.get(
            f"{API_BASE_URL}/db/reconciliation-carte-resume",
            params={"partenaire": partenaire},
            timeout=30
        )
        if r.status_code == 200:
            return r.json()
    except Exception:
        pass
    return None


def charger_table_resume(partenaire):
    try:
        r = requests.get(
            f"{API_BASE_URL}/db/reconciliation-resume",
            params={"partenaire": partenaire},
            timeout=60
        )
        if r.status_code == 200:
            return safe_df(r)
    except Exception:
        pass
    return pd.DataFrame()


