if tab3 is not None:
    with tab3:

        st.markdown(f"#### ✅ Réconciliation (Two Pointers) — {label_choisi}")
        st.caption("Chargez d'abord les données depuis l'onglet « Chargement des données », puis lancez la réconciliation.")

        col_run, col_reload = st.columns(2)

        with col_run:
            lancer = st.button("🚀 Lancer la réconciliation", use_container_width=True, key=f"run_{PARTENAIRE}", type="primary")

        with col_reload:
            recharger = st.button(
                "📥 Recharger le dernier résultat (sans relancer)",
                use_container_width=True,
                key=f"reload_{PARTENAIRE}"
            )

        if lancer:
            try:
                with st.spinner("Réconciliation en cours..."):
                    response = requests.post(
                        f"{API_BASE_URL}/reconciliation/run",
                        params={"partenaire": PARTENAIRE},
                        timeout=300
                    )

                if response.status_code == 200:
                    st.success("Réconciliation terminée")

                    recon_data = pd.read_excel(io.BytesIO(response.content), sheet_name=None)
                    resultat_global = recon_data.get("Resultat_Global", pd.DataFrame())

                    st.session_state[f"recon_resultat_global_{PARTENAIRE}"] = resultat_global
                    st.session_state[f"recon_sheets_{PARTENAIRE}"] = recon_data
                    st.session_state[f"recon_excel_bytes_{PARTENAIRE}"] = response.content
                else:
                    st.error(response.text)

            except Exception as e:
                st.error(f"Erreur réconciliation : {e}")

        if recharger:
            try:
                r = requests.get(f"{API_BASE_URL}/db/reconciliation", params={"partenaire": PARTENAIRE}, timeout=60)
                resultat_global = safe_df(r)

                if resultat_global.empty:
                    st.warning("Aucun résultat de réconciliation trouvé en base pour ce partenaire. Lance d'abord une réconciliation.")
                else:
                    st.success(f"{len(resultat_global)} lignes rechargées depuis la base")
                    st.session_state[f"recon_resultat_global_{PARTENAIRE}"] = resultat_global
                    st.session_state.pop(f"recon_sheets_{PARTENAIRE}", None)
                    st.session_state.pop(f"recon_excel_bytes_{PARTENAIRE}", None)

            except Exception as e:
                st.error(f"Erreur rechargement : {e}")

        if f"recon_resultat_global_{PARTENAIRE}" in st.session_state:

            resultat_global = st.session_state[f"recon_resultat_global_{PARTENAIRE}"]

            st.divider()
            afficher_graphes_reconciliation(PARTENAIRE, hauteur_graphe=HAUTEUR_GRAPHE)

            carte_resume = charger_carte_resume(PARTENAIRE)
            if carte_resume and carte_resume.get("html"):
                st.markdown(carte_resume["html"], unsafe_allow_html=True)

                st.markdown("")
                col_diff1, col_diff2, col_diff3 = st.columns(3)
                col_diff1.metric(
                    "Diff. Montant Partenaire (W2B - B2W)",
                    f"{carte_resume.get('diff_montant_partenaire', '—')} XOF"
                )
                col_diff2.metric(
                    "Diff. Montant Flexcube (W2B - B2W)",
                    f"{carte_resume.get('diff_montant_flexcube', '—')} XOF"
                )
                col_diff3.metric(
                    "Ecart Différence",
                    f"{carte_resume.get('ecart_difference', '—')} XOF"
                )
            else:
                st.info("Aucune donnée de synthèse disponible.")

            st.divider()
            st.markdown("##### 📊 Résumé par statut")

            try:
                r_summary = requests.get(
                    f"{API_BASE_URL}/db/reconciliation-summary",
                    params={"partenaire": PARTENAIRE},
                    timeout=30
                )
                summary = safe_df(r_summary)
            except Exception:
                summary = pd.DataFrame()

            if summary.empty:
                comptes = (
                    resultat_global["STATUT"].value_counts().to_dict()
                    if "STATUT" in resultat_global.columns else {}
                )
                summary = pd.DataFrame(
                    [{"STATUT": s, "NB": int(comptes.get(s, 0))} for s in STATUTS]
                )

            cols = st.columns(len(summary))
            for col, (_, row) in zip(cols, summary.iterrows()):
                col.metric(label_statut(row["STATUT"]), int(row["NB"]))

            st.divider()

            st.markdown("##### 📋 Table résumé")

            table_resume = charger_table_resume(PARTENAIRE)

            statuts_presents = (
                set(resultat_global["STATUT"].dropna().unique().tolist())
                if "STATUT" in resultat_global.columns else set()
            )

            statut_selection = st.multiselect(
                "Filtrer par statut",
                options=STATUTS,
                default=[s for s in STATUTS if s in statuts_presents],
                format_func=label_statut,
                key=f"filtre_{PARTENAIRE}"
            )

            if not table_resume.empty and statut_selection and "Statut" in table_resume.columns:
                table_resume_filtree = table_resume[table_resume["Statut"].isin(statut_selection)]
            else:
                table_resume_filtree = table_resume

            colonnes_resume_ordre = [
                "Type Transaction", "Montant Partenaire", "Montant Flex", "Num_Tel_Client", "Nom_Client",
                "Compte", "Agence", "Ecart Montant", "Diff Heure",
                "Date Fichier Partenaire", "Periode Fichier", "Statut",
            ]
            colonnes_presentes = [c for c in colonnes_resume_ordre if c in table_resume_filtree.columns]

            st.dataframe(
                table_resume_filtree[colonnes_presentes] if colonnes_presentes else table_resume_filtree,
                use_container_width=True,
                height=HAUTEUR_TABLE,
            )
            st.caption(f"{len(table_resume_filtree)} ligne(s) affichée(s) sur {len(table_resume)} au total")

            recon_sheets = st.session_state.get(f"recon_sheets_{PARTENAIRE}")
            if recon_sheets and "Doublon" in recon_sheets and not recon_sheets["Doublon"].empty:
                st.divider()
                st.markdown("##### 🔴 Doublons détectés")
                st.dataframe(recon_sheets["Doublon"], use_container_width=True)

            st.divider()
            if f"recon_excel_bytes_{PARTENAIRE}" in st.session_state:
                st.download_button(
                    "💾 Télécharger le résultat complet (Excel, tous onglets)",
                    data=st.session_state[f"recon_excel_bytes_{PARTENAIRE}"],
                    file_name=f"Resultat_Reconciliation_{PARTENAIRE}.xlsx",
                    mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    use_container_width=True,
                )
            else:
                st.download_button(
                    "💾 Télécharger la vue actuelle (CSV)",
                    data=table_resume_filtree.to_csv(index=False).encode("utf-8"),
                    file_name=f"Resultat_Reconciliation_{PARTENAIRE}.csv",
                    mime="text/csv",
                    use_container_width=True,
                )

        else:
            st.info("Aucun résultat chargé. Clique sur « Lancer la réconciliation » ou « Recharger le dernier résultat ».")


